package kr.memorynotes;import java.util.Arrays;
public class PdfTextRulesTest{public static void main(String[] args){int count=0;for(int extent:new int[]{1,72,595,842,2048})for(float v:new float[]{-1,0,.25f,.5f,1,2}){int point=PdfTextRules.coordinate(v,extent);if(point<0||point>=extent)throw new AssertionError();count++;}for(float n:new float[]{Float.NaN,Float.NEGATIVE_INFINITY,Float.POSITIVE_INFINITY})try{PdfTextRules.coordinate(n,600);throw new AssertionError();}catch(IllegalArgumentException expected){count++;}if(!PdfTextRules.join(Arrays.asList("첫 줄\n","둘째 줄","셋째 줄",null,"")).equals("첫 줄\n둘째 줄\n셋째 줄"))throw new AssertionError();if(!PdfTextRules.join(Arrays.asList("가 ","나")).equals("가 나"))throw new AssertionError();System.out.println("PASS "+(count+2)+" PDF text coordinate/content checks");}}
